#!/usr/bin/env node
// SPDX-License-Identifier: AGPL-3.0-or-later
/*
 * A capture-only SMS webhook for the browser checks, the SMS counterpart of the mail capture.
 *
 * `node scripts/patient-portal-sms-capture.js --serve --port 8496 --file /path/sms.jsonl` listens
 * on 127.0.0.1 only. The portal's PortalSmsSender posts {to, sender_id, message} with
 * "Authorization: Bearer <token>"; the token comes from PATIENT_PORTAL_SMS_WEBHOOK_TOKEN (the same
 * value the portal was started with, generated by the run recipe, never a literal). A message with
 * the right token is appended to the file as one JSON line and answered 200; a wrong or missing
 * token is refused with 401 and nothing is written.
 *
 * readCapturedSmsCode() reads the verification code out of the latest captured message to a
 * number, received after a given time.
 */
'use strict';

const fs = require('node:fs');
const http = require('node:http');

const CODE_PATTERN = /code is (\d{4,10})\b/;
// A verification SMS is a few hundred bytes; anything larger is not the portal.
const MAX_BODY_BYTES = 16 * 1024;

function parseArguments(argv) {
  const options = { serve: false, port: 0, file: '' };
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === '--serve') options.serve = true;
    else if (argument === '--port') options.port = Number(argv[index += 1]);
    else if (argument === '--file') options.file = String(argv[index += 1] || '');
    else throw new Error(`unknown argument ${argument}`);
  }
  return options;
}

function appendCapture(file, entry) {
  const descriptor = fs.openSync(file, 'a', 0o600);
  try {
    fs.writeSync(descriptor, `${JSON.stringify(entry)}\n`);
  } finally {
    fs.closeSync(descriptor);
  }
}

function readCaptures(file) {
  if (!fs.existsSync(file)) return [];
  return fs.readFileSync(file, 'utf8').split('\n').filter(Boolean).map((line) => JSON.parse(line));
}

/** The code in the latest message to `to` received after `after` (ms since epoch), waiting up to `timeoutMs`. */
async function readCapturedSmsCode({ file, to, after = 0, timeoutMs = 15000, wait }) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const match = readCaptures(file)
      .filter((entry) => entry.to === to && Date.parse(entry.receivedAt) > after)
      .pop();
    if (match) {
      const code = CODE_PATTERN.exec(match.message || '');
      if (!code) throw new Error(`captured SMS to ${to} carries no code: ${JSON.stringify(match.message)}`);
      return { code: code[1], senderId: match.senderId, message: match.message };
    }
    if (Date.now() >= deadline) throw new Error(`no SMS to ${to} was captured within ${timeoutMs} ms`);
    await wait(500);
  }
}

function serve({ port, file, token }) {
  if (!token) throw new Error('PATIENT_PORTAL_SMS_WEBHOOK_TOKEN must be set for the capture server');
  if (!file) throw new Error('--file is required');
  const server = http.createServer((request, response) => {
    const answer = (status, body) => {
      response.writeHead(status, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify(body));
    };
    if (request.method !== 'POST') return answer(405, { accepted: false });
    if (request.headers.authorization !== `Bearer ${token}`) return answer(401, { accepted: false });
    let raw = '';
    request.setEncoding('utf8');
    request.on('error', () => answer(400, { accepted: false }));
    request.on('data', (chunk) => {
      raw += chunk;
      if (raw.length > MAX_BODY_BYTES && !response.writableEnded) {
        answer(413, { accepted: false });
        request.destroy();
      }
    });
    return request.on('end', () => {
      if (response.writableEnded) return undefined;
      let body;
      try {
        body = JSON.parse(raw);
      } catch {
        return answer(400, { accepted: false });
      }
      appendCapture(file, {
        receivedAt: new Date().toISOString(),
        to: body.to,
        senderId: body.sender_id,
        message: body.message,
      });
      return answer(200, { accepted: true });
    });
  });
  server.listen(port, '127.0.0.1', () => {
    console.log(`sms capture listening on 127.0.0.1:${server.address().port}, writing ${file}`);
  });
  return server;
}

if (require.main === module) {
  const options = parseArguments(process.argv.slice(2));
  if (!options.serve) throw new Error('use --serve --port <port> --file <capture file>');
  serve({ port: options.port, file: options.file, token: process.env.PATIENT_PORTAL_SMS_WEBHOOK_TOKEN || '' });
}

module.exports = { CODE_PATTERN, parseArguments, readCapturedSmsCode, readCaptures, serve };
